#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>

static long minflt(void) {
    struct rusage ru;
    getrusage(RUSAGE_SELF, &ru);
    return ru.ru_minflt;
}

int main(void) {
    size_t n = 64UL << 20;   /* 64 MiB, above the mmap threshold */
    long f0 = minflt();
    char *p = malloc(n);     /* reserves address space only */
    if (!p) return 1;
    long f1 = minflt();
    for (size_t i = 0; i < n; i += 4096)
        p[i] = 1;            /* first write to each 4 KiB page */
    long f2 = minflt();
    printf("malloc: %ld faults, touch: %ld faults\n",
           f1 - f0, f2 - f1);
    free(p);
    return 0;
}
